// Filtro: solo lead con email valida e azienda chiara
const items = $input.all();
return items.filter(it => {
  const p = it.json;
  return p.email && p.email.includes('@') && p.organization && p.organization.name;
}).map(it => {
  const p = it.json;
  return { json: {
    full_name: p.name,
    first_name: p.first_name,
    last_name: p.last_name,
    email: p.email,
    title: p.title,
    linkedin_url: p.linkedin_url,
    company: p.organization.name,
    company_website: p.organization.website_url,
    company_size: p.organization.estimated_num_employees,
    company_industry: p.organization.industry,
    city: p.city,
    country: p.country,
    source: 'apollo',
    fetched_at: new Date().toISOString()
  }};
});

