// Estrai JSON dalla risposta del modello e mergia con il lead originale
const items = $input.all();
return items.map(it => {
  const lead = $('Filter & normalize').itemMatching(it.itemIndex || 0).json;
  let parsed = { score: 0, reason: 'parse_error', niche: 'altro', priority: 'bassa' };
  try {
    const text = it.json.message?.content?.[0]?.text || it.json.text || it.json.content || '';
    const match = text.match(/\{[\s\S]*\}/);
    if (match) parsed = JSON.parse(match[0]);
  } catch (e) {
    parsed.reason = 'parse_error: ' + e.message;
  }
  return { json: { ...lead, ...parsed } };
});

// Aggrega per il summary Telegram
const all = $input.all();
const total = all.length;
const hi = all.filter(i => (i.json.score || 0) >= 70).length;
const mid = all.filter(i => { const s = i.json.score || 0; return s >= 40 && s < 70; }).length;
const lo = all.filter(i => (i.json.score || 0) < 40).length;
const top = [...all].sort((a, b) => (b.json.score || 0) - (a.json.score || 0)).slice(0, 3)
  .map(i => `• *${i.json.full_name}* (${i.json.company}) — score ${i.json.score} · ${i.json.priority}`)
  .join('\n');
return [{ json: { total, hi, mid, lo, top } }];
